Here, add the updateTerrain method + the terrainView for probing + swapWorld/dispose integration. Place updateTerrain after planetsView. Also, hide the slab top when mounting.

updateTerrain:

```ts
/**
 * TASK-84: drive the single streamed terrain mount. Feed = the predicted
 * ship pose while flying, the character position on foot. Runs the pure
 * terrainPlanetFor decision (hysteresis), tears down / builds the
 * streamer + scene on change, and runs the 4 ms/frame update + sync.
 */
private updateTerrain(dtSec: number): void {
  const feed = this.isOnFoot && this.characterPos ? this.characterPos : this.selfPos;
  if (!feed || !this.system || !this.worldGroup) return;
  const target = terrainPlanetFor(feed, this.system, this.terrainPlanetId);
  if (target !== this.terrainPlanetId) this.swapTerrain(target);
  const streamer = this.terrainStreamer;
  const scene = this.terrainScene;
  if (!streamer || !scene) {
    this.lastTerrainPos = feed;
    return;
  }
  // Horizontal speed of the feed (the streamer expands the 7x7 ring at/above
  // FAST_TRAVEL_SPEED; on foot the speed is walking pace).
  let speed = 0;
  if (this.lastTerrainPos && dtSec > 0) {
    speed = Math.hypot(feed.x - this.lastTerrainPos.x, feed.z - this.lastTerrainPos.z) / dtSec;
  }
  this.lastTerrainPos = feed;
  streamer.update(feed.x, feed.z, speed);
  scene.sync(feed.x, feed.z, speed);
}
```

swapTerrain(target: string | null):

```ts
private swapTerrain(targetId: string | null): void {
  // Tear down the previous mount (scene owns the merged geometries, the
  // streamer owns the chunk geometries — both must be freed).
  if (this.terrainScene) {
    if (this.worldGroup) this.worldGroup.remove(this.terrainScene.group);
    this.terrainScene.dispose();
  }
  if (this.terrainStreamer) {
    this.terrainStreamer.reset();
  }
  this.terrainScene = null;
  this.terrainStreamer = null;
  this.terrainPlanetId = null;
  // Reveal every island top; the mount below hides the mounted one.
  for (const body of this.planetBodies) body.slabTop.visible = true;
  this.lastTerrainPos = null;
  if (!targetId || !this.system || !this.worldGroup) return;
  const index = this.system.planets.findIndex((p) => p.id === targetId);
  if (index < 0) return;
  const planet: Planet = this.system.planets[index];
  const anchor = planetAnchor(index);
  const pad = this.pads.find((p) => p.planetId === planet.id);
  const streamer = new ChunkStreamer(this.seed, planet, {
    pad,
    chunkFilter: (cx, cz) => chunkInSurface(cx, cz, anchor),
  });
  const scene = new ChunkScene(streamer, { monitor: frameMonitor });
  this.worldGroup.add(scene.group);
  this.terrainStreamer = streamer;
  this.terrainScene = scene;
  this.terrainPlanetId = planet.id;
  const body = this.planetBodies[index];
  if (body) body.slabTop.visible = false;
}
```

